final class RouteDraft {
    let id: Int
    var title: String
    init(id: Int, title: String) { self.id = id; self.title = title }
}
func retitle(_ draft: RouteDraft, to title: String) {
    draft.title = title
}
let original = RouteDraft(id: 12, title: "Утро")
let alias = original
retitle(alias, to: "Вечер")
print(original.title)
print(original === alias)

Вывод «Вечер», true. let сохраняет ссылку в переменной, но разрешает изменение var title её объекта. Функция не заменяет ссылку вызывающей стороны, поэтому inout не требуется.

