struct RouteNote {
    let id: Int
    var text: String
}
func annotated(_ route: RouteNote, to text: String) -> RouteNote {
    var draft = route
    draft.text = text
    return draft
}
let original = RouteNote(id: 12, text: "Без заметки")
let draft = annotated(original, to: "Взять камеру")
print(original.text)
print(draft.text)

Вывод «Без заметки», «Взять камеру». Ссылка внутри модели потребует отдельного решения о совместном изменении.
